from pathlib import Path
import json,base64
R=Path(__file__).resolve().parents[2];O=R/'renders/sky_peak_canonique_v1';m=json.loads((O/'manifest.json').read_text())
def uri(p):return 'data:image/png;base64,'+base64.b64encode(p.read_bytes()).decode()
d={'modes':{mode:{n:uri(O/mode/(n+'.png')) for n in names if n!='07_fleurs'} for mode,names in m['modes'].items()},'flowers':{mode:[uri(O/'fleurs'/mode/f'{f:02}.png') for f in range(32)] for mode in ['jour','nuit']},'reference':uri(R/'source/sky_peak_v1/gif_0.png')}
h='''<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sky Peak · layout de référence</title><style>*{box-sizing:border-box}body{background:#122638;color:#ebf3f4;font:16px system-ui;margin:0}header,main,footer{max-width:1120px;margin:auto;padding:24px}h1{font-size:28px;margin:8px 0}p{color:#b4cedd;line-height:1.6}.tag{color:#b1e1a9;font-size:12px;letter-spacing:2px}.bar{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:22px}select,button{background:#294d59;color:white;border:1px solid #709ca3;padding:10px;border-radius:6px}.view{display:grid;grid-template-columns:1fr 255px;gap:22px}canvas{width:100%;image-rendering:pixelated;background:#253a46}aside{padding:16px;background:#1d3948;border-radius:8px}label{display:block;font-size:14px;margin:14px 0}a{color:#b7eac9}small{color:#bed0d9}@media(max-width:780px){.view{grid-template-columns:1fr}}</style><header><div class="tag">TERRAIN ORIGINAL / FLEURS ANIMÉES / NUAGES WRAP</div><h1>Sky Peak — la falaise de la référence</h1><p>La géométrie de la falaise vient directement du GIF : aucune nouvelle disposition de plateau. Fleurs assorties sur un calque animé, panorama montagneux et deux couches de nuages indépendantes.</p></header><main><div class="bar"><select id="mode"><option value="jour">Jour</option><option value="nuit">Nuit</option></select><select id="speed"><option value="smooth">32 phases · 1,6 s</option><option value="native">4 clés · rythme source 0,8 s</option></select><button id="pause">Pause</button><button id="reference">Voir référence fixe</button><button id="png">Exporter PNG</button></div><div class="view"><section><canvas id="view" width="504" height="504"></canvas><p id="clock"></p></section><aside><b>Calques séparés</b><div id="layers"></div><small>↓ exporte la frame courante du calque. Les nuages bouclent tous les 504 px, pas à chaque cycle de fleurs.</small></aside></div><p>Corail doux, pêche, crème et mauve. Les 4 clés proviennent des pétales du GIF, recolorés sans déplacer les fleurs ; les 32 phases sont une interpolation alpha plus lente. Les surfaces cachées par les pétales ont été complétées localement.</p></main><footer><small>Les WebP courts animent seulement les fleurs ; le wrap long est visible ici. Terrain 504×504 sans redimensionnement. Panorama/nuages générés guidés par les références, non certifiés natifs. Aucun mod PMDO modifié.</small></footer><script>const D=__DATA__;function im(s){const i=new Image();i.src=s;return i}const modes=Object.fromEntries(Object.entries(D.modes).map(([m,l])=>[m,Object.fromEntries(Object.entries(l).map(([n,s])=>[n,im(s)]))])),flowers=Object.fromEntries(Object.entries(D.flowers).map(([m,a])=>[m,a.map(im)])),ref=im(D.reference);let mode='jour',speed='smooth',running=true,time=0,last=null,reference=false;const c=document.getElementById('view'),ctx=c.getContext('2d'),visible={},names={'01_ciel':'Ciel','02_etoiles':'Étoiles','03_lune_halo':'Lune et halo','04a_nuages_lointains_wrap':'Nuages lointains · wrap','04b_montagnes':'Montagnes','04c_nuages_proches_wrap':'Nuages proches · wrap','05_sol_et_rebord_herbeux':'Sol et rebord herbeux','06_paroi_et_rochers':'Paroi et rochers','07_fleurs':'Fleurs animées'};function fidx(){return speed==='native'?(Math.floor(time/200)%4)*8:Math.floor(time/50)%32}function save(src,n){const a=document.createElement('a');a.href=src;a.download=n;a.click()}for(const [k,n]of Object.entries(names)){visible[k]=true;const l=document.createElement('label'),ch=document.createElement('input'),a=document.createElement('a');ch.type='checkbox';ch.checked=true;ch.onchange=()=>visible[k]=ch.checked;a.href='#';a.textContent=' ↓';a.onclick=e=>{e.preventDefault();save(k==='07_fleurs'?D.flowers[mode][fidx()]:D.modes[mode][k],k+'.png')};l.append(ch,document.createTextNode(' '+n),a);document.getElementById('layers').append(l)}document.getElementById('mode').onchange=e=>mode=e.target.value;document.getElementById('speed').onchange=e=>speed=e.target.value;document.getElementById('pause').onclick=e=>{running=!running;e.target.textContent=running?'Pause':'Reprendre'};document.getElementById('reference').onclick=e=>{reference=!reference;e.target.textContent=reference?'Voir résultat':'Voir référence fixe'};document.getElementById('png').onclick=()=>save(c.toDataURL(),'sky_peak_'+mode+'.png');function draw(i,x=0){if(i.complete&&i.naturalWidth)ctx.drawImage(i,x,0)}function frame(t){if(last!==null&&running)time+=t-last;last=t;ctx.clearRect(0,0,504,504);if(reference)draw(ref);else for(const k of Object.keys(names)){if(!visible[k])continue;if(k==='07_fleurs'){draw(flowers[mode][fidx()]);continue}const image=modes[mode][k];if(k.includes('wrap')){const rate=k.startsWith('04a')?2:6;const x=-Math.floor(time*rate/1000)%504;draw(image,x);draw(image,x+504)}else draw(image)}document.getElementById('clock').textContent='Fleurs : '+(speed==='native'?fidx()/8+1:fidx()+1)+'/'+(speed==='native'?4:32)+' · nuages : −2 / −6 px/s · wraps 252 / 84 s';requestAnimationFrame(frame)}requestAnimationFrame(frame);</script></html>'''
(R/'apercu_sky_peak_canonique_v1.html').write_text(h.replace('__DATA__',json.dumps(d)),encoding='utf8')
